const isSessionActive = `-- name: IsSessionActive :one
SELECT EXISTS (
    SELECT 1
    FROM auth_sessions s
    JOIN users u ON u.id = s.user_id
    WHERE s.id = $1
      AND s.user_id = $2
      AND s.revoked_at IS NULL
      AND s.expires_at > now()
      AND u.status = 'active'
      AND u.email_verified_at IS NOT NULL
)::boolean AS active
`

type IsSessionActiveParams struct {
	ID     uuid.UUID
	UserID uuid.UUID
}

// Checked on every authenticated request, so a revoked session, an expired one,
// a disabled user or an unproven email stops working at once instead of when
// the access token expires.
func (q *Queries) IsSessionActive(ctx context.Context, arg IsSessionActiveParams) (bool, error) {
	row := q.db.QueryRow(ctx, isSessionActive, arg.ID, arg.UserID)
	var active bool
	err := row.Scan(&active)
	return active, err
}

const listActiveSessions = `-- name: ListActiveSessions :many
SELECT id, provider, client, device_name, device_type, last_ip, last_used_at, created_at
FROM auth_sessions
WHERE user_id = $1 AND revoked_at IS NULL AND expires_at > now()
ORDER BY last_used_at DESC
`

type ListActiveSessionsRow struct {
	ID         uuid.UUID
	Provider   string
	Client     string
	DeviceName string
	DeviceType string
	LastIp     *netip.Addr
	LastUsedAt time.Time
	CreatedAt  time.Time
}

func (q *Queries) ListActiveSessions(ctx context.Context, userID uuid.UUID) ([]ListActiveSessionsRow, error) {
	rows, err := q.db.Query(ctx, listActiveSessions, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListActiveSessionsRow{}
	for rows.Next() {
		var i ListActiveSessionsRow
		if err := rows.Scan(
			&i.ID,
			&i.Provider,
			&i.Client,
			&i.DeviceName,
			&i.DeviceType,
			&i.LastIp,
			&i.LastUsedAt,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

